const STORAGE='cs-bachelors-independent-v2-data';
const DEMO_ID='course-demo';
const CURRICULUM_FILE='./curriculum.json';
let curriculumStages=[];
let curriculumLessonIndex=new Map();
const lessonMetadata=l=>curriculumLessonIndex.get(l?.id)||l||{};
let syllabusStatus='جارٍ تحميل المنهج...';
const seed=()=>({version:2,courses:[{id:'cs101',code:'CS101',title:'مدخل علوم الحاسب والبرمجة',description:'Introduction to Computer Science and Programming',status:'completed',completedAt:'2026-11-23',completionSource:'self_report',lessons:[],isSeeded:true},{id:DEMO_ID,code:'DEMO',title:'التفاضل — مقرر تجريبي',description:'مثال لتجربة الشاشات؛ ليس جزءًا مؤكدًا من منهجك',status:'active',lessons:[{id:'lesson-demo',title:'مفهوم المشتقة',objective:'فهم المشتقة باعتبارها معدل تغير وميل المماس',sections:{},notes:[],quizAnswers:{},createdAt:new Date().toISOString()}],isDemo:true}],activeCourse:DEMO_ID,activeLesson:'lesson-demo',theme:'light',fontSize:17,apiModel:'gemini-3-flash-preview',sync:{owner:'',repo:'',branch:'main',file:'v2-user-progress.json',lastSync:null},activity:[]});
function load(){try{const x=JSON.parse(localStorage.getItem(STORAGE));return x&&x.version===2&&Array.isArray(x.courses)?x:seed()}catch{return seed()}}
// V2.3: source units remain available as historical entries; new leaf lessons use stable IDs.
function stableLessonId(code,index){return `syllabus-${code}-${String(index+1).padStart(2,'0')}`}
function mergeCurriculum(data,stages){
 if(!data||!Array.isArray(data.courses)||!Array.isArray(stages))return false;
 let changed=false;
 for(const stage of stages)for(const source of stage.courses||[]){
  const code=String(source.code||'').trim();if(!code)continue;
  let target=data.courses.find(c=>c.code===code&&!c.isDemo);
  if(!target){target={id:`syllabus-course-${code}`,code,title:source.name,description:'',status:'active',lessons:[],curriculumSource:source.origin||'expanded',stageId:stage.id};data.courses.push(target);changed=true}
  if(target.isSeeded&&code==='CS101'&&target.title!==source.name){target.title=source.name;changed=true}
  if(target.stageId!==stage.id){target.stageId=stage.id;changed=true}
  if(JSON.stringify(target.prereqs)!==JSON.stringify(source.prereqs||[])){target.prereqs=[...(source.prereqs||[])];changed=true}
  if(!Array.isArray(target.lessons)){target.lessons=[];changed=true}
  if(!Array.isArray(target.units)||JSON.stringify(target.units)!==JSON.stringify(source.units||[])){target.units=source.units||[];changed=true}
  // Old wide-topic lessons are not deleted or overwritten. They remain reachable as an archive if previously generated.
  (source.legacyUnits||[]).forEach((u,i)=>{
   const id=stableLessonId(code,i);
   const old=target.lessons.find(l=>l.id===id||l.title===u.title);
   if(old&&!old.legacyOverview){old.legacyOverview=true;changed=true}
  });
  const approvedLessonIds=new Set((source.lessons||[]).map(x=>x.id));
  for(const prev of target.lessons){
   if(!approvedLessonIds.has(prev.id)&&prev.curriculumSource==='expanded'&&!prev.legacyOverview){prev.legacyOverview=true;changed=true}
  }
  (source.lessons||[]).forEach((item,i)=>{
   const lessonId=item.id||stableLessonId(code,i);
   let old=target.lessons.find(l=>l.id===lessonId);
   if(!old){target.lessons.push({id:lessonId,title:item.title,unitIndex:item.unitIndex??0,sections:{},notes:[],quizAnswers:{},completed:false,curriculumSource:'expanded'});changed=true}
   else {if(old.unitIndex!==item.unitIndex){old.unitIndex=item.unitIndex??0;changed=true}if(old.title!==item.title){old.title=item.title;changed=true}if(old.legacyOverview){old.legacyOverview=false;changed=true}}
  });
  if(code==='CS101'&&target.status==='completed'&&!target.completionSource){target.completionSource='self_report';changed=true}
 }
 return changed;
}
function preserveOnImport(incoming){
 if(curriculumStages.length)mergeCurriculum(incoming,curriculumStages);
 return incoming;
}
async function bootstrapCurriculum(){
 try{
  const response=await fetch(CURRICULUM_FILE,{cache:'no-cache'});
  if(!response.ok)throw Error('HTTP '+response.status);
  const data=await response.json();
  if(!Array.isArray(data.stages)||data.stages.length!==6||data.schemaVersion!==2)throw Error('نسخة المنهج غير متوافقة');
  const total=data.stages.reduce((n,s)=>n+(s.courses||[]).reduce((m,c)=>m+(c.lessons||[]).length,0),0);
  if(total<400)throw Error('المنهج الموسع ناقص: '+total);
  curriculumStages=data.stages;
  curriculumLessonIndex=new Map(data.stages.flatMap(st=>st.courses.flatMap(c=>c.lessons.map(l=>[l.id,l]))));
  const changed=mergeCurriculum(db,curriculumStages);
  if(changed)save();
  syllabusStatus=`منهج تجريبي Master: ${data.stages.length} مراحل، ${data.stages.reduce((n,st)=>n+st.courses.length,0)} مادة، ${total} محاضرة بمواصفات تعلم`;
 }catch(e){syllabusStatus='تعذر تحميل المنهج: '+e.message;console.error('Curriculum unavailable',e)}
 render();
}
let db=load(),view='home',detail='reading',running=false,quizSelection={},labCoef=1,interactiveValue=1,activityAnswers={},filter='all',search='',noticeTimer;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const save=()=>{
 try{localStorage.setItem(STORAGE,JSON.stringify(db))}
 catch(e){notify('مساحة التخزين المحلي امتلأت! صدّر نسخة احتياطية أو احذف محتوى قديم.');console.error('Storage quota exceeded',e)}
};
const course=()=>db.courses.find(c=>c.id===db.activeCourse)||db.courses[0];
const lesson=()=>course()?.lessons?.find(x=>x.id===db.activeLesson)||course()?.lessons?.[0];
function notify(msg){const e=$('#toast');if(!e)return;e.textContent=msg;e.style.display='block';clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>e.style.display='none',4500)}
const navigationPositions=new Map();
let navIndex=Number(history.state?.journeyNavIndex)||0;
function route(v,d,options={}){
 if(!options.fromHistory){navigationPositions.set(navIndex,window.scrollY);navIndex+=1;history.pushState({journeyNavIndex:navIndex,view:v,detail:d||detail,courseId:db.activeCourse,lessonId:db.activeLesson},'',`#${v}`)}
 view=v;if(d)detail=d;
 if(v==='lesson'&&detail==='quiz')quizSelection={...(lesson()?.quizAnswers||{})};
 render();
 window.scrollTo({top:options.fromHistory?(navigationPositions.get(navIndex)||0):0,behavior:'instant'});
}
function back(){if(navIndex>0)history.back();else if(view==='lesson')route('course');else if(view==='course')route('library');else route('home')}
window.addEventListener('popstate',e=>{
 const st=e.state;
 if(st?.journeyNavIndex!==undefined){navigationPositions.set(navIndex,window.scrollY);navIndex=st.journeyNavIndex;db.activeCourse=st.courseId||db.activeCourse;db.activeLesson=st.lessonId||db.activeLesson;route(st.view,st.detail,{fromHistory:true})}
 else{navIndex=0;route('home',null,{fromHistory:true})}
});
// Native Android edge-back already dispatches popstate. In standalone PWA only, add a controlled edge swipe fallback.
let edgeTouch=null;
document.addEventListener('touchstart',e=>{if(!matchMedia('(display-mode: standalone)').matches||e.touches.length!==1)return;const t=e.touches[0],width=innerWidth;if(t.clientX<24||t.clientX>width-24)edgeTouch={x:t.clientX,y:t.clientY}} ,{passive:true});
document.addEventListener('touchend',e=>{if(!edgeTouch||!e.changedTouches.length)return;const t=e.changedTouches[0],dx=t.clientX-edgeTouch.x,dy=t.clientY-edgeTouch.y;const valid=((edgeTouch.x<24&&dx>90)||(edgeTouch.x>innerWidth-24&&dx< -90))&&Math.abs(dy)<65;edgeTouch=null;if(valid)back()},{passive:true});
function currentTitle(){return ({home:'الرئيسية',library:'المقررات',course:'المقرر',lesson:'المذاكرة',notes:'الملاحظات',progress:'تقدمي',settings:'الإعدادات',knowledge:'شبكة المعرفة'})[view]||'المذاكرة'}
const symbols={home:'⌂',library:'▣',lesson:'▤',notes:'▧',progress:'◉',settings:'⚙',knowledge:'⬡'};
function button(label,action,classes='secondary',extra=''){return `<button class="btn ${classes}" data-act="${action}" ${extra}>${label}</button>`}
function header(){return `<header class="top"><div><div class="brand">CS BACHELOR'S JOURNEY V3</div><h1>${currentTitle()}</h1></div><div style="display:flex;gap:7px">${view!=='home'?`<button class="icon-btn" data-act="back" aria-label="رجوع">→</button>`:''}<button class="icon-btn" data-act="search" aria-label="بحث">⌕</button><button class="icon-btn" data-view="settings" aria-label="الإعدادات">⚙</button></div></header>`}
function nav(){return `<nav class="bottom-nav" aria-label="التنقل">${[['home','الرئيسية'],['library','المقررات'],['lesson','المذاكرة'],['notes','ملاحظاتي'],['progress','التقدم']].map(([id,name])=>`<button class="nav-btn ${view===id?'selected':''}" data-view="${id}"><span class="sym">${symbols[id]}</span><span>${name}</span></button>`).join('')}</nav>`}
const academicCourses=()=>db.courses.filter(c=>!c.isDemo&&c.id!==DEMO_ID);
const completed=()=>academicCourses().filter(c=>c.status==='completed').length;
function home(){const c=course(),l=lesson();return `<div class="eyebrow">YOUR LEARNING SPACE</div><a href="./studio.html" style="display:block;padding:16px;margin-bottom:12px;border-radius:12px;background:#6553bf;color:white;text-decoration:none">Learning Studio V3.2.7 — Hardware Lab ←</a><a href="./logic.html" style="display:block;padding:12px;margin-bottom:12px;border-radius:12px;background:#e8e2fc;color:#41347f;text-decoration:none">Logic Gates &amp; Circuit Builder ←</a><a href="./alu.html" style="display:block;padding:12px;margin-bottom:12px;border-radius:12px;background:#e8e2fc;color:#41347f;text-decoration:none">Combinational Logic &amp; ALU ←</a><a href="./sequential.html" style="display:block;padding:12px;margin-bottom:12px;border-radius:12px;background:#e8e2fc;color:#41347f;text-decoration:none">Sequential Logic &amp; Registers ←</a><a href="./memory.html" style="display:block;padding:12px;margin-bottom:12px;border-radius:12px;background:#e8e2fc;color:#41347f;text-decoration:none">Memory &amp; Control Unit ←</a><a href="./integrated.html" style="display:block;padding:12px">Integrated CPU &amp; Datapath ←</a><a class="btn secondary" href="./integrated.html#hardware">عرض العتاد ثلاثي الأبعاد</a><h1 class="hero-title">كمّل رحلتك التعليمية</h1><p class="muted">كل درس ليه شرح وتفاعلات ومختبر واختبار مستقل، وكل جزء بيتحفظ بعد توليده.</p><div class="feature"><div class="small" style="color:#a6c5ff">الدرس الحالي</div><h2>${esc(l?.title||'ابدأ درس جديد')}</h2><p>${esc(c?.title||'')}</p>${button('متابعة المذاكرة ←','openLesson','')}<div style="height:8px"></div></div><div class="section-title"><h2>التقدم الدراسي</h2><span class="tag">مكتمل بالتأكيد من تسجيلك</span></div><div class="grid"><div class="metric"><b>${completed()}</b><span>مقررات مكتملة</span></div><div class="metric"><b>${academicCourses().length}</b><span>مقررات مسجلة</span></div></div><div class="section-title"><h2>المقررات</h2><button class="pill" data-view="library">عرض الكل ←</button></div>${db.courses.filter(c=>c.status==='completed').slice(0,1).concat(db.courses.filter(c=>c.isDemo).slice(0,1)).map(courseCard).join('')}<div class="section-title"><h2>الوصول السريع</h2></div><div class="grid">${[['reading','الشرح','▤'],['interactive','التفاعل','✦'],['lab','المختبر','⌁'],['quiz','الاختبار','✓']].map(([id,name,icon])=>`<button class="panel" data-detail="${id}" style="text-align:right;border-color:#e9e6fb;min-height:98px"><span style="font-size:25px;color:#5d54c9">${icon}</span><div style="margin-top:9px;font-weight:780">${name}</div></button>`).join('')}</div>`}
function courseCard(c){const done=c.status==='completed',number=c.lessons?.length||0;return `<article class="course" data-course="${esc(c.id)}"><div class="course-mark">${esc(c.code.slice(0,5))}</div><div style="flex:1;min-width:0"><h3>${esc(c.title)}</h3><p>${esc(c.description||'')} ${c.isDemo?'(تجريبي)':''}</p><div class="bar"><span style="width:${done?100:0}%"></span></div><div class="status" style="margin-top:6px;color:${done?'#219d77':'#726cc0'}">${done?'✓ تم إنهاء المقرر — حتى لو المحتوى مش متولد':`${number} درس مسجل`}</div></div><span style="font-size:24px">‹</span></article>`}
function library(){
 const list=db.courses.filter(c=>(filter==='all'||(filter==='completed'&&c.status==='completed')||(filter==='active'&&c.status!=='completed'))&&(`${c.title} ${c.code}`.toLowerCase().includes(search.toLowerCase())));
 const assigned=new Set();
 const groups=curriculumStages.map(s=>{
  const courses=list.filter(c=>c.stageId===s.id);courses.forEach(c=>assigned.add(c.id));
  if(!courses.length)return '';
  return `<section class="curriculum-stage"><div class="stage-title"><h2>${esc(s.title)}</h2><span class="tag">${courses.length} مواد</span></div><div class="stage-courses">${courses.map(courseCard).join('')}</div></section>`;
 }).join('');
 const extras=list.filter(c=>!assigned.has(c.id));
 return `<div class="eyebrow">COURSE LIBRARY</div><h1 class="hero-title">مكتبتك الدراسية</h1><p class="muted">${esc(syllabusStatus)}. المحتوى القديم لم يُنقل؛ كل درس له توليد مستقل.</p><div class="field"><input id="course-search" placeholder="ابحث عن كورس أو كود..." value="${esc(search)}"></div><div class="tabs">${[['all','الكل'],['active','قيد الدراسة'],['completed','المكتمل']].map(([v,n])=>`<button class="pill ${filter===v?'active':''}" data-filter="${v}">${n}</button>`).join('')}</div>${groups}${extras.length?`<section class="curriculum-stage"><div class="stage-title"><h2>مقررات خارج المنهج / تجريبية</h2></div>${extras.map(courseCard).join('')}</section>`:''}${!list.length?'<div class="empty">مفيش مقررات مطابقة</div>':''}<div style="margin-top:17px">${button('＋ إضافة مقرر جديد','addCourse','full')}</div><p class="fineprint">CS101 مكتمل بتأكيدك الشخصي. مقرر DEMO وتوليداته محفوظين دون تغيير.</p>`
}
function coursePage(){
 const c=course();if(!c)return library();
 const leaf=c.lessons.filter(l=>!l.legacyOverview),archived=c.lessons.filter(l=>l.legacyOverview&&Object.keys(l.sections||{}).length);
 const courseCounts=leaf.length,done=leaf.filter(l=>l.completed).length;
 const renderLessonRow=(l,i)=>`<div class="lesson-row lesson-row-v23"><button class="lesson-link" data-lesson="${esc(l.id)}"><span class="circle">${i+1}</span><span class="lesson-text"><b>${esc(l.title)}</b><small>${Object.keys(l.sections||{}).length} أجزاء متولدة${l.completed?' · مكتمل ✓':''}</small></span><span>‹</span></button><button class="btn tiny ${l.completed?'secondary':'ghost'}" data-toggle-lesson="${esc(l.id)}" aria-label="${l.completed?'إلغاء اكتمال الدرس':'تحديد الدرس كمكتمل'}">${l.completed?'✓ مكتمل':'○ مكتمل'}</button></div>`;
 const unitList=(c.units||[]).map((u,i)=>{const group=leaf.filter(l=>l.unitIndex===i),n=group.filter(l=>l.completed).length;return `<details class="unit-group" ${i===0?'open':''}><summary><span>${esc(u.title)}</span><span class="unit-count">${n}/${group.length} مكتمل</span></summary><div class="unit-lessons">${group.map(renderLessonRow).join('')}</div></details>`}).join('');
 const ungrouped=leaf.filter(l=>!c.units?.some((u,i)=>i===l.unitIndex));
 return `<div class="subject-hero"><div class="small">${esc(c.code)} ${c.isDemo?'· تجريبي':''}</div><h2>${esc(c.title)}</h2>${c.prereqs?.length?`<p class="course-prereqs">المتطلبات: ${esc(c.prereqs.join('، '))}</p>`:''}<p>${c.status==='completed'?'✓ مكتمل':'○ قيد الدراسة'}</p></div><div class="actions">${button(c.status==='completed'?'إلغاء علامة اكتمال المقرر':'اعتبار المقرر مكتمل','toggleCourse','ghost')}${button('＋ إضافة درس','addLesson','secondary')}</div><div class="section-title"><h2>وحدات المقرر والدروس</h2><span class="muted small">${done} / ${courseCounts} مكتمل يدويًا</span></div>${unitList}${ungrouped.length?ungrouped.map(renderLessonRow).join(''):''}${archived.length?`<details class="unit-group"><summary>الدروس القديمة المحتفظ بمحتواها (${archived.length})</summary>${archived.map(renderLessonRow).join('')}</details>`:''}<p class="fineprint">اكتمال الدرس قرارك أنت فقط، ومش مشروط بتوليد الشرح أو حل اختبار.</p>`;
}
