function emptySection(name){return `<div class="empty"><div class="symbol">${({reading:'▤',interactive:'✦',lab:'⌁',quiz:'✓'})[detail]}</div><h3>محتوى ${name} لسه مش متولد</h3><p>اضغط «توليد ${name}» علشان تولّد الجزء ده فقط وتحفظه داخل الدرس.</p></div>`}
function formatRichText(text){
 const str=String(text??'');
 return str.split(/(```[\w+-]*\n[\s\S]*?```)/g).map(part=>{
  const m=part.match(/^```([\w+-]*)\n([\s\S]*?)```$/);
  if(m)return `<pre dir="ltr"><code>${esc(m[2].replace(/\n$/,''))}</code></pre>`;
  return esc(part).replace(/`([^`\n]+)`/g,'<code dir="ltr" style="background:rgba(102,93,226,.14);color:inherit;padding:2px 6px;border-radius:6px;font-family:ui-monospace,Consolas,monospace;font-size:.9em">$1</code>').replace(/\n/g,'<br>');
 }).join('');
}
function renderSection(l,key){const x=l.sections?.[key];if(!x)return emptySection(names[key]);if(key==='reading')return `${x.qualityWarnings?.length?`<div class="panel" style="margin-bottom:12px;border-color:#d8a53b"><b>تنبيه جودة الشرح:</b> ${x.qualityWarnings.map(esc).join(' — ')}. ده تنبيه آلي لا يضمن دقة الشرح العلمية.</div>`:''}<article class="reader" style="--read-size:${db.fontSize||17}px"><h2>${esc(x.title||l.title)}</h2>${(x.blocks||[]).map(b=>`<section>${b.heading?`<h3>${esc(b.heading)}</h3>`:''}${(b.paragraphs||[]).map(p=>`<div style="margin:10px 0 18px">${formatRichText(p)}</div>`).join('')}${b.example?`<div class="callout"><b>مثال:</b><div style="margin-top:6px">${formatRichText(b.example)}</div></div>`:''}</section>`).join('')}</article><div class="panel" style="margin-top:14px"><div class="section-title" style="margin:0 0 12px"><h2>شرح إضافي</h2></div>${(l.explanations||[]).map(e=>`<div class="note-card"><b>${esc(e.question)}</b><div style="margin-top:6px">${formatRichText(e.answer)}</div></div>`).join('')||'<p class="muted small">استخدم «مش فاهم؟» لتوليد شرح إضافي للجزئية اللي تحددها.</p>'}</div>`;if(key==='interactive')return interactiveSection(x,l);if(key==='lab')return labSection(x);if(key==='quiz'){const qs=x.questions||[];return `<div class="panel"><h2>${esc(x.title||'اختبار الدرس')}</h2><p class="muted">اختبر فهمك، وشوف تفسير كل إجابة بعد التصحيح.</p>${qs.map((q,i)=>`<section class="note-card" style="background:#f8f7fe"><b>${i+1}. ${esc(q.question)}</b><div>${(q.options||[]).map((o,k)=>`<button class="option ${quizSelection[i]===k?'selected':''}" data-quiz="${i}" data-choice="${k}">${esc(o)}</button>`).join('')}</div><p class="small" id="quiz-feedback-${i}" aria-live="polite"></p></section>`).join('')}${button('تصحيح الاختبار','gradeQuiz','full')}</div>`}return ''}
function mathBidi(t){return `<bdi dir="ltr" class="math-inline">${esc(t)}</bdi>`}
function taskResponse(t,i,l){const answer=l.activityAnswers?.[i];if(answer===undefined)return '';const right=Number(t.correctIndex||0);const ok=Number(answer)===right;return `<div class="activity-feedback ${ok?'good':'bad'}" aria-live="polite">${ok?'✓ صحيح':'↻ محتاج مراجعة'} — ${esc(t.feedback||'جرّب تحدد العلاقة بين المتغيرات من جديد.')}</div>`}
function interactiveSection(x,l){if(x.kind==='generated_html'){
 const doc=generatedLabDocument(x.html||'');
 return `<div class="panel activity-root"><h2>${esc(x.title||'أنشطة تفاعلية')}</h2><p>${esc(x.description||'جرّب وحل وتحقق من فهمك.')}</p><p class="fineprint">الأنشطة تتفاعل داخل إطار معزول. راجع التصحيح لو ظهر فيه تعارض.</p><iframe title="${esc(x.title||'نشاط تفاعلي')}" sandbox="allow-scripts" referrerpolicy="no-referrer" loading="lazy" style="width:100%;min-height:640px;border:1px solid #dedbf2;border-radius:14px;background:white" srcdoc="${esc(doc)}"></iframe></div>`;
 }const tasks=x.tasks||[];return `<div class="panel activity-root"><div class="activity-heading"><div class="eyebrow">INTERACTIVE DISCOVERY</div><h2>${esc(x.title||'تجارب اكتشاف المفهوم')}</h2><p class="muted">${esc(x.intro||'جرّب وتوقع النتيجة، وبعدها افحص تفسيرها.')}</p></div>${tasks.map((t,i)=>{
 const kind=t.type||'choice';const answer=l.activityAnswers?.[i];let body='';
 if(kind==='slider'){
 const v=Number(l.activitySliders?.[i]??t.start??t.min??0),min=Number(t.min??-5),max=Number(t.max??5),step=Number(t.step??1);
 body=`<div class="field"><label for="activity-range-${i}">غيّر المتغير: <output id="slider-output-${i}">${v}</output></label><input id="activity-range-${i}" data-interactive-index="${i}" type="range" min="${min}" max="${max}" step="${step}" value="${v}"></div><div id="slider-result-${i}" class="activity-feedback">${esc(t.instruction||'حرّك المؤشر وشوف قيمة المتغير بتتغير.')}</div>`;
 }else if(kind==='order'){
 const items=Array.isArray(t.items)?t.items:[];let order=l.activityOrders?.[i];if(!Array.isArray(order)||order.length!==items.length)order=items.map((_,j)=>j);
 body=`<div class="order-list">${order.map((itemIndex,pos)=>`<div class="order-item"><span class="order-num">${pos+1}</span><span>${esc(items[itemIndex])}</span><div class="order-controls"><button data-order="${i}" data-position="${pos}" data-direction="-1" aria-label="نقل الخطوة لأعلى" ${pos===0?'disabled':''}>↑</button><button data-order="${i}" data-position="${pos}" data-direction="1" aria-label="نقل الخطوة لأسفل" ${pos===order.length-1?'disabled':''}>↓</button></div></div>`).join('')}</div><button class="btn secondary" data-check-order="${i}">تحقق من الترتيب</button><div class="activity-feedback" id="order-result-${i}" aria-live="polite">${esc(l.activityOrderResult?.[i]||'رتّب الخطوات باستخدام الأسهم ثم اضغط تحقق.')}</div>`;
 }else{
 body=`<div class="activity-options">${(t.choices||[]).map((choice,k)=>`<button class="option ${answer===k?'selected':''}" data-task="${i}" data-choice="${k}">${esc(choice)}</button>`).join('')}</div>${taskResponse(t,i,l)}`;
 }
 return `<section class="activity-card"><div class="eyebrow">${kind==='slider'?'تجربة':kind==='order'?'رتّب الخطوات':kind==='error_spot'?'اكتشف الخطأ':'توقّع النتيجة'} · ${i+1}/${tasks.length}</div><h3>${esc(t.question||'')}</h3>${body}</section>`
 }).join('')}</div>`}
function labState(){const l=lesson();if(!l)return {a:1,x:1,h:1};const d=l.labState||{};return {a:Number.isFinite(Number(d.a))?Number(d.a):1,x:Number.isFinite(Number(d.x))?Number(d.x):1,h:Number.isFinite(Number(d.h))?Math.max(.05,Number(d.h)):1}}
function generatedLabDocument(html){
 // Isolated opaque-origin frame: even generated JavaScript cannot read localStorage, API keys, or the parent DOM.
 const csp="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; font-src 'none'; connect-src 'none'; form-action 'none'; frame-src 'none'; object-src 'none'; base-uri 'none'";
 const meta=`<meta http-equiv="Content-Security-Policy" content="${csp}">`;
 return '<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8">'+meta+'<meta name="viewport" content="width=device-width, initial-scale=1">'+
 '<style>html{color-scheme:light}body{font:16px system-ui,Arial;margin:16px;background:#fafaff;color:#221d38}button,input,select{font:inherit;max-width:100%}button{cursor:pointer}*{box-sizing:border-box}</style></head><body>'+html+'</body></html>';
}
function labSection(x){if(x.kind==='generated_html'){
 const doc=generatedLabDocument(x.html||'');
 return `<div class="panel"><h2>${esc(x.title||'مختبر تفاعلي')}</h2><p>${esc(x.description||'')}</p><p class="fineprint">محاكاة يولدها النموذج وتعمل داخل بيئة معزولة، بدون وصول لمفتاح API أو بيانات تقدمك. تحقق من صحتها العلمية قبل الاعتماد.</p><iframe title="${esc(x.title||'محاكاة تفاعلية')}" sandbox="allow-scripts" referrerpolicy="no-referrer" loading="lazy" style="width:100%;min-height:580px;border:1px solid #dedbf2;border-radius:14px;background:white" srcdoc="${esc(doc)}"></iframe></div>`;
 }if(x.kind==='none')return `<div class="panel"><h2>${esc(x.title||'لا يحتاج مختبرًا')}</h2><p>${esc(x.description||'')}</p></div>`;
if(x.kind==='electrostatic_charge_transfer'){const d=lesson()?.labCharge||{electrons:10,direction:1,qA:0,qB:0};return `<div class="panel"><h2>${esc(x.title||'انتقال الشحنة')}</h2><p>${esc(x.description||'غيّر عدد الإلكترونات واتجاه انتقالها وتوقّع شحنة كل جسم.')}</p><div class="field"><label>عدد الإلكترونات: <output id="charge-e-count">${d.electrons}</output></label><input type="range" data-charge="electrons" min="0" max="100" step="1" value="${d.electrons}"></div><div class="field"><label>اتجاه انتقال الإلكترونات</label><select data-charge="direction"><option value="1" ${d.direction===1?'selected':''}>من A إلى B</option><option value="-1" ${d.direction===-1?'selected':''}>من B إلى A</option></select></div><div class="field"><label>الشحنة الابتدائية A (بمضاعفات e)</label><input type="number" data-charge="qA" value="${d.qA}" step="1"></div><div class="field"><label>الشحنة الابتدائية B (بمضاعفات e)</label><input type="number" data-charge="qB" value="${d.qB}" step="1"></div><div class="notice" id="charge-results"></div></div>`}const kind=x.kind||'function';if(!['function','derivative_quadratic'].includes(kind))return `<div class="panel"><h2>${esc(x.title||'مختبر علمي')}</h2><p>${esc(x.description||'')}</p><div class="notice">المحاكاة المطلوبة مش موجودة في المحرك حاليًا. مش هنشغّل JavaScript مولّد غير موثوق.</div></div>`;const {a,x:point,h}=labState();return `<div class="panel"><div class="eyebrow">LIVE MATH LAB</div><h2>${esc(x.title||'مختبر المشتقة والمماس')}</h2><p class="muted">${esc(x.description||'غيّر المعامل والنقطة والمسافة، وراقب تغير القاطع والمماس والميل.')}</p><div class="lab-box derivative-lab"><svg id="function-graph" viewBox="0 0 340 290" role="img" aria-label="منحنى تربيعي، خط مماس، وخط قاطع متحرك"></svg></div><div class="lab-legend"><span><i class="legend-curve"></i>الدالة</span><span><i class="legend-tangent"></i>المماس</span><span><i class="legend-secant"></i>القاطع</span></div><div class="lab-controls">${[['a','المعامل a',a,-2,2,.1],['x','موضع النقطة x',point,-2,2,.1],['h','المسافة h',h,.1,2,.1]].map(([key,label,val,min,max,step])=>`<div class="field"><label for="lab-${key}">${label}: <output id="lab-value-${key}" dir="ltr">${Number(val).toFixed(1)}</output></label><input data-lab="${key}" id="lab-${key}" type="range" min="${min}" max="${max}" step="${step}" value="${val}"></div>`).join('')}</div><div class="lab-results" aria-live="polite"><div>الدالة ${mathBidi('f(x)=a·x²')}</div><div>قيمة الدالة: <strong id="lab-fx"></strong></div><div>ميل المماس: <strong id="lab-slope"></strong></div><div>ميل القاطع: <strong id="lab-secant"></strong></div></div><div class="notice">قرب h من الصفر، وقارن ميل القاطع بميل المماس. القيم محسوبة فعليًا من الدالة.</div>${button('إعادة ضبط','resetLab','ghost')}</div>`}
function updateChargeLab(){const el=$('#charge-results');if(!el)return;const d=lesson()?.labCharge||{electrons:10,direction:1,qA:0,qB:0};const e=1.602176634e-19;const A=Number(d.qA)+d.direction*Number(d.electrons),B=Number(d.qB)-d.direction*Number(d.electrons);el.textContent=`الشحنة النهائية A = ${A}e (${(A*e).toExponential(3)} C) | B = ${B}e (${(B*e).toExponential(3)} C) | المجموع قبل وبعد = ${Number(d.qA)+Number(d.qB)}e` ;const count=$('#charge-e-count');if(count)count.textContent=d.electrons}
function drawGraph(){const svg=$('#function-graph');if(!svg)return;const {a,x,h}=labState();const W=340,H=290,sx=52,sy=26,x0=170,y0=145;const px=q=>x0+q*sx,py=q=>y0-q*sy;const f=q=>a*q*q;const m=2*a*x,secant=(f(x+h)-f(x))/h;const n=v=>Number(v).toFixed(2);let grid='';for(let k=-6;k<=6;k++){grid+=`<line x1="${px(k)}" y1="0" x2="${px(k)}" y2="${H}" stroke="var(--graph-grid,#e6e6f3)"/><line x1="0" y1="${py(k)}" x2="${W}" y2="${py(k)}" stroke="var(--graph-grid,#e6e6f3)"/>`}let curve='';for(let i=-3.5;i<=3.5;i+=.025)curve+=`${curve?'L':'M'}${n(px(i))} ${n(py(f(i)))} `;const tangent=q=>f(x)+m*(q-x);const sec=q=>f(x)+secant*(q-x);const q1=-4,q2=4;svg.innerHTML=`<defs><clipPath id="lab-clip"><rect width="${W}" height="${H}" rx="12"/></clipPath></defs><g clip-path="url(#lab-clip)">${grid}<line x1="0" y1="${y0}" x2="${W}" y2="${y0}" stroke="#9296ae" stroke-width="1.6"/><line x1="${x0}" y1="0" x2="${x0}" y2="${H}" stroke="#9296ae" stroke-width="1.6"/><path d="${curve}" fill="none" stroke="#5b52dc" stroke-width="3.5"/><line x1="${n(px(q1))}" y1="${n(py(tangent(q1)))}" x2="${n(px(q2))}" y2="${n(py(tangent(q2)))}" stroke="#0c9e8e" stroke-width="2.5"/><line x1="${n(px(q1))}" y1="${n(py(sec(q1)))}" x2="${n(px(q2))}" y2="${n(py(sec(q2)))}" stroke="#ee9b37" stroke-width="2.2" stroke-dasharray="8 5"/><circle cx="${n(px(x))}" cy="${n(py(f(x)))}" r="6" fill="#0c9e8e" stroke="white" stroke-width="2"/><circle cx="${n(px(x+h))}" cy="${n(py(f(x+h)))}" r="5.5" fill="#ee9b37" stroke="white" stroke-width="2"/></g>`;for(const [id,v]of [['fx',f(x)],['slope',m],['secant',secant]]){const e=$('#lab-'+id);if(e)e.textContent=n(v)} }
function notesPage(){const l=lesson(),notes=db.courses.flatMap(c=>c.lessons.flatMap(q=>(q.notes||[]).map(n=>({...n,lesson:q.title,course:c.title}))));return `<h1 class="hero-title">دفتر الملاحظات</h1><p class="muted">ملاحظاتك مرتبطة بالدروس وتتحفظ محليًا، وتقدر تزامنها يدويًا.</p><div class="panel"><div class="field"><label>أضف ملاحظة للدرس الحالي: ${esc(l?.title||'لم يُحدد درس')}</label><textarea id="note-text" placeholder="اكتب ملاحظتك هنا..." ></textarea></div>${button('حفظ الملاحظة','saveNote','full',!l?'disabled':'')}</div><div class="section-title"><h2>الملاحظات المحفوظة</h2><span class="tag">${notes.length}</span></div>${notes.length?notes.slice().reverse().map(n=>`<div class="note-card"><div class="eyebrow">${esc(n.course)} · ${esc(n.lesson)}</div><p>${esc(n.text)}</p><time>${esc(n.date?.slice(0,10)||'')}</time></div>`).join(''):'<div class="empty">لسه مفيش ملاحظات محفوظة</div>'}<div class="section-title"><h2>شبكة المعرفة</h2>${button('عرض الشبكة','knowledge','ghost tiny')}</div>`}
function knowledgePage(){const all=db.courses.flatMap(c=>c.lessons.flatMap(l=>(l.sections?.reading?.concepts||[]).map(t=>({t,c:c.title,l:l.title}))));return `<h1 class="hero-title">شبكة المعرفة</h1><p class="muted">المفاهيم المتولدة من المحاضرات، مرتبطة بالدروس الأصلية.</p><div class="panel">${all.length?all.map(x=>`<div class="knowledge-item"><span class="dot"></span><div><b>${esc(x.t)}</b><div class="small muted">${esc(x.c)} ← ${esc(x.l)}</div></div></div>`).join(''):`<div class="empty">هتظهر المفاهيم هنا بعد توليد الشرح. الربط بين المفاهيم لسه في مرحلة التطوير.</div>`}</div>`}
function progressPage(){const courses=academicCourses(),count=courses.length,num=completed(),percent=Math.round(100*num/Math.max(1,count));const secs=courses.flatMap(c=>c.lessons.flatMap(l=>Object.keys(l.sections||{})));return `<h1 class="hero-title">تقدمك الدراسي</h1><p class="muted">اكتمال المقرر مش مشروط بتوليد محتواه.</p><div class="panel" style="text-align:center"><div class="progress-ring" style="--amount:${percent}%"><strong>${percent}%</strong></div><h2>${num} من ${count} مقرر مكتمل</h2><p class="fineprint">النسبة للمقررات الدراسية المسجلة فقط؛ المقررات التجريبية لا تدخل في الحساب.</p></div><div class="grid" style="margin-top:13px"><div class="metric"><b>${secs.length}</b><span>أجزاء دروس متولدة</span></div><div class="metric"><b>${courses.reduce((n,c)=>n+c.lessons.length,0)}</b><span>دروس مسجلة</span></div></div><div class="section-title"><h2>حالة المقررات</h2></div>${courses.map(courseCard).join('')}<div class="notice" style="margin-top:15px"><b>CS101 مسجل مكتمل</b><br>اعتمدنا تأكيدك إنك ذاكرته، رغم إن محاضراته مش متولدة في V2. العلامة محفوظة محليًا ويمكن تصديرها ومزامنتها.</div>`}
function settingsPage(){return `<h1 class="hero-title">الإعدادات والمزامنة</h1><div class="panel"><h3>Gemini API</h3><p class="fineprint">توليد المحتوى الحقيقي يحتاج API Key خاص بيك وحصة متاحة. المفتاح محفوظ في ذاكرة التبويب الحالية فقط (localStorage)، ومش بيتضمنه ملف النسخ الاحتياطي.</p><div class="field"><label>Gemini API Key</label><input id="api-key" type="password" placeholder="ألصق المفتاح هنا" autocomplete="off" value="${esc(localStorage.getItem('v2_gemini_key')||'')}"></div><div class="field"><label>الموديل</label><input id="api-model" value="${esc(db.apiModel)}" placeholder="مثال: gemini-3-flash-preview"></div>${button('حفظ إعدادات التوليد','saveApi','secondary')}</div><div class="panel" style="margin-top:12px"><h3>المظهر والقراءة</h3><div class="actions">${button('الوضع '+(db.theme==='dark'?'الفاتح':'الداكن'),'toggleTheme','ghost')}${button('A−','fontDown','ghost')}${button('A+','fontUp','ghost')}</div></div><div class="panel" style="margin-top:12px"><h3>نقل البيانات بين الأجهزة</h3><p class="fineprint">تصدير واستيراد البيانات متاح بدون GitHub أو أي Connector. للمزامنة عبر GitHub استخدم مستودع مستقل وPersonal Access Token بصلاحيات محتويات المستودع فقط؛ التوكن لا يُحفظ في بيانات التطبيق.</p><div class="actions">${button('↓ تصدير نسخة احتياطية','export','secondary')}${button('↑ استيراد نسخة احتياطية','import','ghost')}</div><input type="file" accept="application/json" id="import-file" hidden><div class="sep"></div><div class="field"><label>GitHub Owner</label><input id="sync-owner" value="${esc(db.sync.owner)}" placeholder="اسم حساب GitHub"></div><div class="field"><label>Repository</label><input id="sync-repo" value="${esc(db.sync.repo)}" placeholder="اسم المستودع الجديد"></div><div class="field"><label>Branch</label><input id="sync-branch" value="${esc(db.sync.branch)}"></div><div class="field"><label>GitHub PAT — مؤقت في التبويب فقط</label><input id="sync-token" type="password" placeholder="لا تشارك التوكن" autocomplete="off" value="${esc(localStorage.getItem('v2_github_pat')||'')}"></div><p class="fineprint">آخر مزامنة ناجحة: ${esc(db.sync.lastSync||'لم تتم')}</p><div class="actions">${button('↓ سحب من GitHub','pullSync','ghost')}${button('↑ رفع إلى GitHub','pushSync','secondary')}</div><p class="fineprint">قبل السحب أو الرفع صدّر نسخة احتياطية. الرفع يستبدل ملف V2 المحدد فقط، ولا يلمس progress.json الخاص بالمشروع القديم.</p></div><div class="panel" style="margin-top:12px"><h3>النسخة التجريبية</h3>${button('حذف المقرر التجريبي','removeDemo','warn')}<p class="fineprint">مقرر CS101 المكتمل لا يتأثر بحذف المقرر التجريبي.</p></div>`}
function render(){document.body.classList.toggle('dark',db.theme==='dark');const pages={home,library,course:coursePage,lesson:lessonPage,notes:notesPage,progress:progressPage,settings:settingsPage,knowledge:knowledgePage};$('#app').innerHTML=`<div class="app-shell">${header()}<main class="page">${(pages[view]||home)()}</main>${nav()}</div>`;if(view==='lesson'&&detail==='lab'){drawGraph();updateChargeLab()}}
function id(){return 'item-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7)}
async function askPrompt(title,placeholder){return window.prompt(title,placeholder||'')}
async function onAction(action){if(running&&['generateOne','generateAll','explain'].includes(action))return;const c=course(),l=lesson();switch(action){case 'back':back();break;case 'openLesson':route('lesson','reading');break;case 'goLibrary':route('library');break;case 'goNotes':route('notes');break;case 'search':route('library');setTimeout(()=>$('#course-search')?.focus(),100);break;case 'addCourse':{const title=(await askPrompt('اسم المقرر الجديد'))?.trim();if(!title)return;const code=(await askPrompt('كود المقرر (اختياري)','NEW'))?.trim()||'NEW';const obj={id:id(),code,title,status:'active',description:'',lessons:[]};db.courses.push(obj);db.activeCourse=obj.id;db.activeLesson=null;save();route('course');break}case 'addLesson':{const title=(await askPrompt('عنوان الدرس الجديد'))?.trim();if(!title)return;const objective=(await askPrompt('هدف الدرس (اختياري)',''))?.trim()||'';const obj={id:id(),title,objective,sections:{},notes:[],createdAt:new Date().toISOString()};c.lessons.push(obj);db.activeLesson=obj.id;save();route('lesson','reading');break}case 'toggleLesson':{if(!l)return;l.completed=!l.completed;l.completedAt=l.completed?new Date().toISOString():null;l.completionSource='manual';save();render();notify(l.completed?'تم تسجيل الدرس مكتملًا':'تم إلغاء اكتمال الدرس');break}case 'toggleCourse':{c.status=c.status==='completed'?'active':'completed';c.completedAt=c.status==='completed'?new Date().toISOString().slice(0,10):null;c.completionSource='manual';save();render();notify('اتحفظت حالة المقرر');break}case 'saveNote':{const t=$('#note-text')?.value.trim();if(!t||!l){notify('اكتب ملاحظة الأول');return}l.notes=l.notes||[];l.notes.push({text:t,date:new Date().toISOString()});save();render();notify('اتحفظت الملاحظة');break}case 'knowledge':route('knowledge');break;case 'generateOne':await generateSection(detail);break;case 'generateAll':await generateAll();break;case 'explain':await explain();break;case 'resetLab':if(l){l.labState={a:1,x:1,h:1};save()}render();break;case 'gradeQuiz':gradeQuiz();break;case 'saveApi':localStorage.setItem('v2_gemini_key',$('#api-key').value.trim());db.apiModel=$('#api-model').value.trim()||'gemini-3-flash-preview';save();notify('اتحفظت الإعدادات في التبويب');break;case 'toggleTheme':db.theme=db.theme==='dark'?'light':'dark';save();render();break;case 'fontDown':db.fontSize=Math.max(14,(db.fontSize||17)-1);save();render();break;case 'fontUp':db.fontSize=Math.min(27,(db.fontSize||17)+1);save();render();break;case 'fontReset':db.fontSize=17;save();render();break;case 'export':exportData();break;case 'import':$('#import-file')?.click();break;case 'pushSync':await githubSync('push');break;case 'pullSync':await githubSync('pull');break;case 'removeDemo':{const demo=db.courses.find(x=>x.id===DEMO_ID);if(!demo){notify('المقرر التجريبي اتحذف بالفعل');break}if(!confirm('حذف المقرر التجريبي ودروسه؟'))break;db.courses=db.courses.filter(x=>x.id!==DEMO_ID);db.activeCourse=db.courses[0]?.id;db.activeLesson=db.courses[0]?.lessons?.[0]?.id||null;save();route('library');break}default:break}}
function gradeQuiz(){const l=lesson(),qs=l?.sections?.quiz?.questions||[];if(!l||!qs.length)return;let score=0;qs.forEach((q,i)=>{const chosen=quizSelection[i],right=Number(q.correctIndex||0),ok=chosen===right;if(ok)score++;const node=$(`#quiz-feedback-${i}`);if(node)node.innerHTML=`<span style="color:${ok?'#178b70':'#c14848'}">${chosen===undefined?'لم تتم الإجابة':ok?'✓ إجابة صحيحة':'✕ إجابة غير صحيحة'}</span> — ${esc(q.explanation||'')}<div class="math-answer">الإجابة الصحيحة: ${esc(q.options?.[right]||'')}</div>`});l.quizAnswers={...(l.quizAnswers||{}),...quizSelection};l.lastQuiz={score,total:qs.length,date:new Date().toISOString(),answers:{...quizSelection}};save();notify(`نتيجة الاختبار: ${score}/${qs.length}`)}
async function gemini(prompt,mode='standard'){
 const key=localStorage.getItem('v2_gemini_key');if(!key)throw Error('أضف Gemini API Key من الإعدادات أولًا.');
 const model=db.apiModel||'gemini-3-flash-preview';
 const url=`https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:generateContent`;
 const outputLimit=['reading','lab','interactive'].includes(mode)?12288:8192;
 let response;
 try{response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','x-goog-api-key':key},body:JSON.stringify({contents:[{role:'user',parts:[{text:prompt}]}],generationConfig:{responseMimeType:'application/json',temperature:mode==='reading'?.25:.4,maxOutputTokens:outputLimit}})})}catch{throw Error('تعذر الاتصال بـGemini. تحقق من الإنترنت أو إعدادات المتصفح.')}
 const raw=await response.text();let result;try{result=JSON.parse(raw)}catch{throw Error(`استجابة غير متوقعة من Gemini: ${response.status}`)}
 if(!response.ok){let msg=result.error?.message||`HTTP ${response.status}`;if(response.status===429)msg='وصلت لحد Gemini API أو انتهت الحصة المتاحة. '+msg;throw Error(msg)}
 const candidate=result.candidates?.[0];const finish=candidate?.finishReason;
 if(finish==='MAX_TOKENS'||finish==='CONTINUATION')throw Error('Gemini وقف عند حد الإخراج قبل ما يكمل. لم يُستبدل الشرح القديم.');
 if(finish!=='STOP')throw Error('Gemini لم يؤكد اكتمال الإجابة ('+(finish||'سبب غير معروف')+'). لم يُحفظ محتوى غير مكتمل.');
 const txt=(candidate.content?.parts||[]).filter(p=>typeof p.text==='string').map(p=>p.text).join('');
 if(!txt.trim())throw Error('Gemini رجع رد فاضي؛ المحتوى القديم لم يتغير.');
 try{const data=JSON.parse(txt.replace(/^```(?:json)?\s*/i,'').replace(/```$/,'').trim());if(!data||typeof data!=='object'||Array.isArray(data))throw Error('نوع JSON غير صحيح');Object.defineProperty(data,'_usage',{value:{promptTokens:result.usageMetadata?.promptTokenCount??null,outputTokens:result.usageMetadata?.candidatesTokenCount??null,totalTokens:result.usageMetadata?.totalTokenCount??null,finishReason:finish},enumerable:false});return data}
 catch{throw Error('Gemini رجع JSON غير مكتمل أو غير صالح. لم نستبدل المحتوى القديم.')}
}
function promptFor(key,l,c){
 const courseName=c.title;
 const lessonName=l.title;
 const lessons=(c.lessons||[]).filter(x=>!x.legacyOverview);
 const idx=lessons.findIndex(x=>x.id===l.id);
 const prevTitle=idx>0?lessons[idx-1].title:'';
 const nextTitle=idx>=0&&idx<lessons.length-1?lessons[idx+1].title:'';
 const contextLine=(prevTitle||nextTitle)?`السياق داخل المقرر: ${prevTitle?`الدرس السابق كان «${prevTitle}»`:'بداية المقرر'}${nextTitle?`، والدرس التالي سيكون «${nextTitle}»`:''}.\n`:'';
 const base=`أنت أستاذ جامعي متخصص في ${courseName}. اسم الطالب ميسي؛ نادِه باسمه مرة واحدة فقط في المحاضرة كلها عند الحاجة ومن غير تكرار. الشرح بالمصري الواضح والمصطلح الإنجليزي عند الحاجة مع تعريفه، من غير حشو أو ترحيب متكرر.\nالمادة: ${courseName}\nالمحاضرة: ${lessonName}\n${contextLine}`;
 const integrity='الأولوية القصوى للدقة العلمية والتقنية. راجع داخليًا كل تعريف وقانون وأمر ومثال ونتيجته قبل الرد. لا تخمّن ولا تستخدم تبسيطًا مضللًا. اشرح أي مصطلح جديد قبل استخدامه. ';
 const sandboxRules='شروط تقنية إلزامية لحقل html: أرجع محتوى الـ body فقط (<div>...</div><style>...</style><script>...</script>) بدون <!doctype> أو <html> أو <head> أو <meta> أو <link> أو <iframe> أو <form> أو <base>. ممنوع نهائيًا استخدام onclick أو oninput أو أي معالج أحداث داخل وسوم HTML؛ اربط كل الأحداث باستخدام addEventListener داخل <script> فقط. لا تستخدم fetch أو import أو أي مكتبات أو روابط خارجية.';
 switch(key){
  case 'reading':return base+integrity+`المطلوب محاضرة جامعية شاملة، عميقة، ومسترسلة للتعلم الذاتي، وليست ملخصًا مختصرًا. ابنِ المحاضرة تلقائيًا من فهمك العميق للمادة وعنوان الحصة وسياقها: ابدأ بالمشكلة الحقيقية التي يحلها هذا الموضوع، ثم غطِّ كل الجوانب الأساسية والتفاصيل العملية والحالات الحدية بفقرات مترابطة ومسترسلة توضح ماذا يحدث وكيف ولماذا دون اختصار مخل. لا تذكر أداة أو مفهومًا دون مثال عملي يوضحه. اعرض أمثلة تطبيقية متدرجة تبدأ بحالة أولية وتتبع التنفيذ خطوة بخطوة مع سبب كل نتيجة، وأضف مثالًا يوضح خطأ شائعًا وكيفية تجنبه. تنسيق الكود إلزامي: أي كود برمجي متعدد الأسطر داخل paragraphs أو example يجب وضعه داخل علامات كود Markdown مع سطور جديدة فعلية (\\n) ومسافات بادئة (Indentation) مضبوطة هكذا: \`\`\`python\\n...\\n\`\`\`، وأي مصطلح برمجي قصير داخل السطر يوضع بين backticks مثل \`while\`. JSON فقط بالشكل: {"title":"...","blocks":[{"heading":"...","paragraphs":["فقرة تفسيرية مسترسلة ومكتملة","فقرة تالية متصلة بها"],"example":"مثال متدرج بكود منسق ونتيجته"}],"concepts":["..."]}.`;
  case 'interactive':return base+integrity+`صمّم تلقائيًا من 2 إلى 4 أنشطة تفاعلية متدرجة تناسب موضوع «${lessonName}» (توقع النتيجة، تجربة، اكتشاف خطأ) مع تصحيح فوري مفسّر بناءً على إجابة الطالب. ${sandboxRules} أرجع JSON فقط: {"kind":"generated_html","title":"...","description":"...","html":"<div>...</div><style>...</style><script>...</script>"}.`;
  case 'lab':{
   const m=lessonMetadata(l);
   if(m.lab?.model==='electrostatic_charge_transfer')return base+integrity+'المحاكي المتاح هو نقل الشحنة بين جسمين. أنشئ له عنوانًا ووصفًا علميين صحيحين وفق المحاضرة. JSON فقط: {"kind":"electrostatic_charge_transfer","title":"...","description":"..."}.';
   if(/derivative|quadratic/i.test(m.lab?.model||''))return base+integrity+'المحاكي المتاح للمشتقة التربيعية. JSON فقط: {"kind":"derivative_quadratic","title":"...","description":"..."}.';
   return base+integrity+`صمّم تلقائيًا مختبرًا أو محاكيًا تفاعليًا حقيقيًا يناسب «${lessonName}» في مادة «${courseName}» ويساعد الطالب على اكتشاف الفكرة بالتجربة العملية. يجب أن يحتوي على عناصر تحكم (أزرار/منزلقات/مدخلات) تغيّر حالة النموذج العلمي أو البرمجي فوريًا مع عرض مرئي واضح للنتائج (Canvas أو SVG أو DOM تفاعلي) وتعليمات مختصرة. لا تكتفِ بنص أو أسئلة اختيار؛ المختبر لازم يحاكي أو يحسب الحالة فعليًا ويتحدث عند تغيير المدخلات. ${sandboxRules} لو طبيعة الدرس نظرية بحتة ولا تسمح بمحاكاة مفيدة أعد {"kind":"none","title":"لا يحتاج مختبرًا","description":"سبب محدد"}. JSON فقط بالشكل: {"kind":"generated_html","title":"...","description":"...","html":"<div>...</div><style>...</style><script>...</script>"}.`;
  }
  case 'quiz':return base+integrity+'أنشئ 8 أسئلة تقيس الفهم والتطبيق العملي في هذه المحاضرة، بإجابات صحيحة وتفسير واضح لكل إجابة. أعد JSON فقط: {"title":"...","questions":[{"question":"...","options":["...","...","...","..."],"correctIndex":0,"explanation":"..."}]}.';
  default:throw Error('نوع توليد غير معروف');
 }
}
function readingQualityWarnings(data){
 // تنبيهات غير حاسمة؛ طول النص وعدد الأقسام لا يثبتان جودة الشرح علميًا.
 const blocks=data.blocks||[];
 const warnings=[];
 if(!blocks.some(b=>typeof b.example==='string'&&b.example.trim()))warnings.push('لا يوجد مثال تطبيقي واضح؛ راجع جودة الشرح');
 return warnings;
}
function ensureReadingComplete(data){
 // يُرفض فقط المحتوى التالف بنيويًا؛ اكتمال الرد نفسه يُفحص عبر finishReason في gemini().
 if(!Array.isArray(data.blocks)||!data.blocks.length)throw Error('Gemini رجّع شرحًا بلا أقسام. لم يُستبدل الشرح القديم.');
 if(!data.blocks.every(b=>b&&typeof b==='object'&&!Array.isArray(b)&&typeof b.heading==='string'&&b.heading.trim()&&Array.isArray(b.paragraphs)&&b.paragraphs.length&&b.paragraphs.every(p=>typeof p==='string')&&b.paragraphs.some(p=>p.trim())))throw Error('أحد أقسام الشرح ناقص أو تالف. لم يُستبدل الشرح القديم.');
 if(data.blocks.every(b=>!b.paragraphs.some(p=>p.trim().length>=15)))throw Error('الشرح خالٍ من فقرات مفهومة. لم يُستبدل الشرح القديم.');
}
function validateGeneratedHtml(data){
 if(typeof data.html!=='string'||!data.html.trim()||data.html.length>75000)throw Error('ملف المختبر فارغ أو أكبر من الحد المدعوم');
 if(!/<(?:button|input|select|textarea)\b/i.test(data.html)||!/<script\b/i.test(data.html))throw Error('المختبر لا يحتوي على مدخلات ومنطق تشغيل');
 if(/<script\b[^>]*\bsrc\s*=|<iframe\b|<form\b|<base\b|<object\b|<embed\b|<meta\b[^>]*http-equiv|<link\b/i.test(data.html))throw Error('المحتوى المولد يحتوي على عناصر أو موارد خارجية غير مسموحة');
 if(/<[a-z][^>]*\s+on[a-z]+\s*=|\b(?:src|href|action)\s*=\s*["']?\s*javascript\s*:/i.test(data.html))throw Error('المحتوى المولد يستعمل معالجات غير آمنة للأحداث');
 if(!/<\/script\s*>/i.test(data.html))throw Error('كود JavaScript غير مكتمل');
}
function valid(key,data){
 if(!data||typeof data!=='object'||Array.isArray(data))throw Error('استجابة الموديل مش بالشكل المطلوب.');
 if(key==='reading'){
  if(typeof data.title!=='string'||!data.title.trim())throw Error('عنوان الشرح ناقص');
  ensureReadingComplete(data);
  if(data.concepts!==undefined&&(!Array.isArray(data.concepts)||data.concepts.some(x=>typeof x!=='string')))throw Error('قائمة المفاهيم غير سليمة');
 }
 if(key==='interactive'){
  if(data.kind==='generated_html'){validateGeneratedHtml(data)}
  else{
   if(!Array.isArray(data.tasks)||!data.tasks.length)throw Error('الأنشطة ناقصة');
   for(const t of data.tasks){
    if(!t||typeof t!=='object'||!['choice','error_spot','slider','order'].includes(t.type))throw Error('نوع نشاط غير مدعوم');
    if(typeof t.question!=='string'||!t.question.trim())throw Error('سؤال النشاط ناقص');
    if(['choice','error_spot'].includes(t.type)&&(!Array.isArray(t.choices)||t.choices.length<2||t.choices.some(x=>typeof x!=='string'||!x.trim())||!Number.isInteger(t.correctIndex)||t.correctIndex<0||t.correctIndex>=t.choices.length))throw Error('اختيارات النشاط أو إجابته غير سليمة');
    if(t.type==='order'){
     const items=t.items||[],correct=t.correctOrder||[];
     if(!Array.isArray(items)||items.length<2||items.some(x=>typeof x!=='string'||!x.trim())||!Array.isArray(correct)||correct.length!==items.length||new Set(correct).size!==items.length||correct.some(v=>!Number.isInteger(v)||v<0||v>=items.length))throw Error('ترتيب خطوات النشاط مش صالح');
    }
    if(t.type==='slider'&&(!Number.isFinite(Number(t.min))||!Number.isFinite(Number(t.max))||Number(t.min)>=Number(t.max)||!Number.isFinite(Number(t.step))||Number(t.step)<=0))throw Error('قيم شريط النشاط غير صالحة');
   }
  }
 }
 if(key==='quiz'){
  if(!Array.isArray(data.questions)||!data.questions.length)throw Error('الاختبار ناقص');
  for(const [i,q] of data.questions.entries()){
   if(!q||typeof q.question!=='string'||!q.question.trim()||!Array.isArray(q.options)||q.options.length<2||q.options.length>8||q.options.some(o=>typeof o!=='string'||!o.trim())||new Set(q.options.map(o=>o.trim())).size!==q.options.length||!Number.isInteger(q.correctIndex)||q.correctIndex<0||q.correctIndex>=q.options.length||typeof q.explanation!=='string'||!q.explanation.trim())throw Error(`السؤال ${i+1} ناقص اختيارًا صحيحًا أو تفسيرًا أو فيه خيارات متكررة`);
  }
 }
 if(key==='lab'){
  if(!data.kind)throw Error('نوع المختبر مفقود');
  if(data.kind==='generated_html')validateGeneratedHtml(data);
  else if(!['electrostatic_charge_transfer','derivative_quadratic','function','none'].includes(data.kind))throw Error('نوع المختبر غير معروف');
  if(data.kind==='none'&&(!data.description||typeof data.description!=='string'))throw Error('سبب عدم الحاجة للمختبر ناقص');
 }
}
// Smoke-test generated JavaScript in an opaque-origin iframe, NEVER in the app's own context.
// This checks startup syntax/runtime errors, not scientific accuracy or every interaction path.
async function validateGeneratedHtmlRuntime(html){
 if(typeof document==='undefined'||typeof window==='undefined')throw Error('اختبار المتصفح غير متاح');
 const token='probe-'+Math.random().toString(36).slice(2)+Date.now();
 const pre=`<script>window.__labProbeErrors=[];addEventListener('error',function(e){window.__labProbeErrors.push(String(e.message||'JavaScript error'))});addEventListener('unhandledrejection',function(e){window.__labProbeErrors.push(String(e.reason||'Promise rejection'))});<\/script>`;
 const post=`<script>setTimeout(function(){parent.postMessage({type:'v2-lab-probe',token:${JSON.stringify(token)},errors:window.__labProbeErrors||[],controls:document.querySelectorAll('button,input,select,textarea').length},'*')},160);<\/script>`;
 const frame=document.createElement('iframe');
 frame.setAttribute('sandbox','allow-scripts');frame.setAttribute('referrerpolicy','no-referrer');
 frame.setAttribute('aria-hidden','true');frame.style.cssText='position:fixed;left:-10000px;top:0;width:800px;height:600px;opacity:0;pointer-events:none;';
 const source=generatedLabDocument(pre+html+post);
 return new Promise((resolve,reject)=>{
  let done=false;
  const cleanup=()=>{window.removeEventListener('message',received);clearTimeout(timer);frame.remove()};
  const finish=(err)=>{if(done)return;done=true;cleanup();err?reject(err):resolve(true)};
  const received=e=>{
   if(e.source!==frame.contentWindow||e.data?.type!=='v2-lab-probe'||e.data.token!==token)return;
   if(e.data.errors?.length)return finish(Error('JavaScript في المختبر لا يعمل: '+e.data.errors[0]));
   if(!e.data.controls)return finish(Error('المختبر لا يحتوي على عنصر تحكم ظاهر'));
   finish();
  };
  const timer=setTimeout(()=>finish(Error('تعذر اختبار تشغيل المختبر داخل الإطار المعزول')),4000);
  window.addEventListener('message',received);
  frame.srcdoc=source;document.body.appendChild(frame);
 });
}
async function generateSection(key,fromBatch=false){const c=course(),l=lesson();if(!l){notify('اختار درس الأول');return false}if(!fromBatch){running=true;render()}try{const spec=promptFor(key,l,c);if(spec===null){notify("المختبر محدد في المنهج لكنه غير قابل للتشغيل في المحرك الحالي؛ لم نستهلك طلب Gemini.");return false}const data=await gemini(spec,key);valid(key,data);if(['interactive','lab'].includes(key)&&data.kind==='generated_html')await validateGeneratedHtmlRuntime(data.html);const usage=data._usage;if(key==='reading')data.qualityWarnings=readingQualityWarnings(data);l.sections=l.sections||{};l.sections[key]=data;l.generatedAt=l.generatedAt||{};l.generatedAt[key]=new Date().toISOString();l.generatedUsage=l.generatedUsage||{};l.generatedUsage[key]=usage;db.activity.push({kind:key,date:new Date().toISOString(),lessonId:l.id});save();notify(key==='reading'&&data.qualityWarnings?.length?`اتحفظ الشرح، ومعه ${data.qualityWarnings.length} ملاحظة جودة شكلية.`:`✓ تم توليد ${names[key]} وحفظه`);return true}catch(e){notify(`تعذر توليد ${names[key]}: ${e.message}`);return false}finally{if(!fromBatch){running=false;render()}}}
async function generateAll(){if(running)return;running=true;render();const l=lesson();if(!l){running=false;render();return}let ok=0;for(const key of ['reading','interactive','lab','quiz']){if(l.sections?.[key])continue;const result=await generateSection(key,true);if(result)ok++;else{if(!confirm(`فشل توليد ${names[key]}. هل تريد متابعة بقية أجزاء الدرس؟`))break}}running=false;render();notify(`اكتمل توليد ${ok} أجزاء جديدة. كل جزء ناجح محفوظ مستقل.`)}
async function explain(){const l=lesson();if(!l||!l.sections?.reading){notify('ولّد الشرح أولًا');return}const selection=window.getSelection()?.toString().trim().slice(0,1000)||'';const q=prompt('اكتب النقطة اللي مش فاهمها، أو ظلّل نص الشرح ثم اضغط الزر',selection);if(!q?.trim())return;running=true;render();try{const x=await gemini(`اشرح النقطة التالية من الصفر شرحًا علميًا دقيقًا باللهجة المصرية، بتشبيه ثم مثال محلول ثم تطبيق، في درس ${l.title}. السؤال: ${q}. الرد JSON فقط: {"answer":"شرح تفصيلي متعدد الفقرات"}`);if(!x.answer)throw Error('الشرح الإضافي ناقص');l.explanations=l.explanations||[];l.explanations.push({question:q,answer:x.answer,date:new Date().toISOString()});save();notify('تم حفظ الشرح الإضافي تحت المحاضرة')}catch(e){notify(e.message)}finally{running=false;render()}}
function exportData(){const blob=new Blob([JSON.stringify({...db,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='cs-bachelors-v2-backup.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('تم تصدير نسخة احتياطية')}
async function importData(file){try{const x=JSON.parse(await file.text());if(x.version!==2||!Array.isArray(x.courses))throw Error('ملف مش متوافق مع V2');if(!confirm('استيراد الملف هيستبدل البيانات المحلية الحالية. هل صدّرت نسخة احتياطية؟'))return;db=preserveOnImport(x);save();route('home');notify('تم استيراد البيانات والمنهج محفوظ')}catch(e){notify('فشل الاستيراد: '+e.message)}}
function syncValues(){db.sync.owner=$('#sync-owner')?.value.trim()||db.sync.owner;db.sync.repo=$('#sync-repo')?.value.trim()||db.sync.repo;db.sync.branch=$('#sync-branch')?.value.trim()||'main';localStorage.setItem('v2_github_pat',$('#sync-token')?.value.trim()||'');save()}
async function githubSync(mode){syncValues();const {owner,repo,branch,file}=db.sync,token=localStorage.getItem('v2_github_pat');if(!owner||!repo||!token){notify('اكمل Owner وRepository وGitHub Token');return}const endpoint=`https://api.github.com/repos/${encodeURIComponent(owner)}/${encodeURIComponent(repo)}/contents/${encodeURIComponent(file)}`,headers={'Accept':'application/vnd.github+json','Authorization':`Bearer ${token}`,'X-GitHub-Api-Version':'2022-11-28'};try{const get=await fetch(endpoint+`?ref=${encodeURIComponent(branch)}`,{headers});let existing=null;if(get.ok)existing=await get.json();else if(get.status!==404)throw Error(`GitHub HTTP ${get.status}`);if(mode==='pull'){if(!existing){notify('لسه مفيش ملف مزامنة V2 في المستودع');return}const b64=existing.content.replace(/\s/g,'');const bytes=Uint8Array.from(atob(b64),c=>c.charCodeAt(0));const text=new TextDecoder().decode(bytes);const x=JSON.parse(text);if(x.version!==2||!Array.isArray(x.courses))throw Error('ملف تقدم غير متوافق');if(!confirm('السحب هيستبدل البيانات الموجودة محليًا. صدّر نسخة احتياطية قبل الاستمرار.'))return;const currentSync=db.sync;db=preserveOnImport(x);db.sync={...db.sync,...currentSync,lastSync:new Date().toISOString()};save();route('home');notify('اكتملت مزامنة السحب')}else{if(!confirm('الرفع هيستبدل ملف بيانات V2 على GitHub. هل حفظت نسخة احتياطية؟'))return;const copy={...db,sync:{...db.sync,lastSync:new Date().toISOString()}};const bytes=new TextEncoder().encode(JSON.stringify(copy));let bin='';for(let i=0;i<bytes.length;i+=8192)bin+=String.fromCharCode(...bytes.subarray(i,i+8192));const content=btoa(bin);const body={message:"Sync CS Bachelor's Journey V2 data",content,branch};if(existing?.sha)body.sha=existing.sha;const put=await fetch(endpoint,{method:'PUT',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify(body)});if(!put.ok){const err=await put.text();throw Error(`GitHub HTTP ${put.status}: ${err.slice(0,180)}`)}db.sync.lastSync=copy.sync.lastSync;save();render();notify('اكتملت مزامنة الرفع')}}catch(e){notify('فشل المزامنة: '+e.message)}}
function delegate(e){const el=e.target.closest('[data-view],[data-act],[data-course],[data-lesson],[data-detail],[data-filter],[data-quiz],[data-task],[data-order],[data-check-order],[data-toggle-lesson]');if(!el)return;if(el.dataset.view){route(el.dataset.view);return}if(el.dataset.detail){route('lesson',el.dataset.detail);return}if(el.dataset.course){db.activeCourse=el.dataset.course;db.activeLesson=course()?.lessons?.[0]?.id||null;save();route('course');return}if(el.dataset.toggleLesson){const l=course()?.lessons?.find(v=>v.id===el.dataset.toggleLesson);if(l){l.completed=!l.completed;l.completedAt=l.completed?new Date().toISOString():null;l.completionSource='manual';save();render()}return}if(el.dataset.lesson){db.activeLesson=el.dataset.lesson;save();route('lesson','reading');return}if(el.dataset.filter){filter=el.dataset.filter;render();return}if(el.dataset.quiz!==undefined){const i=Number(el.dataset.quiz),k=Number(el.dataset.choice);quizSelection[i]=k;const l=lesson();if(l){l.quizAnswers={...(l.quizAnswers||{}),...quizSelection};save()}document.querySelectorAll(`[data-quiz="${i}"]`).forEach(n=>n.classList.toggle('selected',Number(n.dataset.choice)===k));return}if(el.dataset.task!==undefined){const i=Number(el.dataset.task),k=Number(el.dataset.choice),l=lesson();if(!l)return;l.activityAnswers={...(l.activityAnswers||{}),[i]:k};save();render();return}if(el.dataset.order!==undefined){const i=Number(el.dataset.order),p=Number(el.dataset.position),direction=Number(el.dataset.direction),l=lesson(),t=l?.sections?.interactive?.tasks?.[i];if(!t?.items)return;l.activityOrders=l.activityOrders||{};let order=l.activityOrders[i]||t.items.map((_,j)=>j);order=[...order];const dest=p+direction;if(dest<0||dest>=order.length)return;[order[p],order[dest]]=[order[dest],order[p]];l.activityOrders[i]=order;l.activityOrderResult=l.activityOrderResult||{};delete l.activityOrderResult[i];save();render();return}if(el.dataset.checkOrder!==undefined){const i=Number(el.dataset.checkOrder),l=lesson(),t=l?.sections?.interactive?.tasks?.[i];if(!t)return;const order=l.activityOrders?.[i]||t.items.map((_,j)=>j),ok=JSON.stringify(order)===JSON.stringify(t.correctOrder);l.activityOrderResult=l.activityOrderResult||{};l.activityOrderResult[i]=(ok?'✓ الترتيب صحيح. ':'↻ الترتيب مش صحيح. ')+(t.feedback||'');save();render();return}if(el.dataset.act)onAction(el.dataset.act)}
document.addEventListener('click',delegate);document.addEventListener('input',e=>{const target=e.target;if(target.dataset.charge){const l=lesson();if(l){l.labCharge=l.labCharge||{electrons:10,direction:1,qA:0,qB:0};l.labCharge[target.dataset.charge]=Number(target.value);save()}updateChargeLab();return}if(target.dataset.lab){const l=lesson();if(l){l.labState={...labState(),[target.dataset.lab]:Number(target.value)};save()}const out=$('#lab-value-'+target.dataset.lab);if(out)out.textContent=Number(target.value).toFixed(1);drawGraph();return}if(target.dataset.interactiveIndex!==undefined){const i=Number(target.dataset.interactiveIndex),v=Number(target.value),l=lesson();if(l){l.activitySliders=l.activitySliders||{};l.activitySliders[i]=v;save()}const n=$(`#slider-output-${i}`);if(n)n.textContent=v;const result=$(`#slider-result-${i}`);if(result)result.textContent='القيمة الآن '+v+' — '+(l?.sections?.interactive?.tasks?.[i]?.feedback||'راقب تغير القيمة.');return}if(target.id==='course-search'){search=target.value;const p=target.selectionStart;render();const input=$('#course-search');input?.focus();input?.setSelectionRange(p,p)}});
document.addEventListener('change',e=>{if(e.target.dataset.charge){const l=lesson();if(l){l.labCharge=l.labCharge||{electrons:10,direction:1,qA:0,qB:0};l.labCharge[e.target.dataset.charge]=Number(e.target.value);save()}updateChargeLab();return}if(e.target.id==='import-file'&&e.target.files?.[0])importData(e.target.files[0])});
if(!localStorage.getItem(STORAGE))save();if(!history.state?.journeyNavIndex){history.replaceState({journeyNavIndex:0,view:'home',detail:'reading',courseId:db.activeCourse,lessonId:db.activeLesson},'',location.pathname+location.search)}
if('serviceWorker'in navigator&&location.protocol!=='file:')window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));render();bootstrapCurriculum();
